'use server'

import { refresh } from 'next/cache'
import { cookies } from 'next/headers'

// Simulate a database
const DB = {
  preferences: {
    notifications: false, // Default
  }
}

// Helper to get preference (simulating DB read)
// In a real app, this would be a DB query
export async function getNotificationPreference() {
  // We use cookies to simulate user-specific preference storage for the demo
  // In a real app, you might fetch this from a DB based on the user's session
  const cookieStore = await cookies()
  const hasPreference = cookieStore.has('notifications_enabled')
  return hasPreference ? cookieStore.get('notifications_enabled')?.value === 'true' : false
}

export async function toggleNotificationPreference() {
  // 1. Update the data
  const currentPreference = await getNotificationPreference()
  const newPreference = !currentPreference

  // Simulate DB update (using cookies for persistence in this demo)
  const cookieStore = await cookies()
  // Setting a cookie in a Server Action automatically triggers a re-render of the current page.
  // However, to demonstrate the "refresh" function as requested for generic data updates:
  cookieStore.set('notifications_enabled', String(newPreference))

  // 2. Refresh the current page
  // This function refreshes the client router, ensuring the UI reflects the latest state.
  // It is the recommended way to refresh the current view from a Server Action without redirecting.
  // Note: If your data is cached (e.g., fetch with default cache), you should use revalidatePath or revalidateTag instead.
  refresh() 
}

