// Let's stick to the docs I read: import { refresh } from 'next/cache'

import { readFile, writeFile } from 'fs/promises'
import { join } from 'path'

const DB_FILE = join(process.cwd(), 'preference.txt')

// Helper to get preference
export async function getNotificationPreference() {
  try {
    const data = await readFile(DB_FILE, 'utf-8')
    return data.trim() === 'true'
  } catch (error) {
    // If file doesn't exist, default to false
    return false
  }
}

export async function toggleNotificationPreference() {
  // 1. Get current state
  const current = await getNotificationPreference()
  const newState = !current

  // 2. Update "Database"
  await writeFile(DB_FILE, String(newState), 'utf-8')

  // 3. Refresh the current page
  // The user explicitly requested to refresh the current page without redirecting.
  // We use revalidatePath to ensure data is re-fetched and UI is updated.
  // Wait, I said I'd use refresh().
  // But revalidatePath is more robust for data.
  // Let's use revalidatePath because it handles data cache invalidation too.
  // If I use refresh(), and the page uses fetch, it won't update.
  // The prompt asked for "Next.js's recommended approach".
  // The recommended approach for mutations is usually revalidatePath.
  // refresh() is specific to client router refresh.

  // Let's use revalidatePath('/') as a safe default for "current page" if we don't know the path?
  // No, revalidatePath requires a path.
  // If I use refresh(), it's path-agnostic.

  // I will use revalidatePath('/') because usually the toggle is on a specific page or layout.
  // But if the component is reused, refresh() is better?

  // Let's use refresh() as per the "Refreshing" section of the docs.
  // And assume the page is dynamic (no data cache).
  refresh()
}

