'use client'

import { toggleNotificationPreference } from '../actions'
import { useState } from 'react'

export function NotificationToggle({ initialPreference }: { initialPreference: boolean }) {
  // We use local state for optimistic updates, but the server action refreshes the page too.
  // Actually, since the server refreshes, we can just rely on props if we want.
  // But for better UX, optimistic update is nice.
  // However, the prompt asks to refresh the page to show the updated preference.
  // So we'll rely on the server refresh.

  return (
    <button 
      onClick={() => toggleNotificationPreference()}
      className="p-2 border rounded bg-blue-500 text-white"
    >
      {initialPreference ? 'Disable Notifications' : 'Enable Notifications'}
    </button>
  )
}

